-- SELECT only. Save before apply. System catalogs and the migration history only (no app table rows).
-- 바뀌는 것 전부의 되돌릴 기준: 챙길 것 표 6개의 RLS·표 권한·정책·트리거(이 migration은 2개 표에 정책 하나·트리거 하나씩만 더함), 재사용하는 두 함수, 기록.
select 'function' as kind,p.oid::regprocedure::text as name,p.prosecdef::text||':'||coalesce(p.proconfig::text,'none')||':'||coalesce(p.proacl::text,'none')||':'||md5(p.prosrc) as definition
  from pg_proc p where p.oid in(to_regprocedure('private.app_operator_feature_guard()'),to_regprocedure('private.app_workspace_has_feature(uuid,text)'))
union all select 'trigger',c.relname::text||'.'||t.tgname::text,t.tgenabled::text||':'||pg_get_triggerdef(t.oid) from pg_trigger t join pg_class c on c.oid=t.tgrelid where t.tgrelid in(to_regclass('public.app_todo_candidates'),to_regclass('public.app_todo_ask_rooms'),to_regclass('public.app_todo_radar_state'),to_regclass('public.app_todo_not_mine'),to_regclass('public.app_todo_feedback'),to_regclass('public.app_todo_rules')) and not t.tgisinternal
union all select 'table',c.relname::text,c.relrowsecurity::text||':'||c.relforcerowsecurity::text||':'||coalesce(c.relacl::text,'none') from pg_class c where c.oid in(to_regclass('public.app_todo_candidates'),to_regclass('public.app_todo_ask_rooms'),to_regclass('public.app_todo_radar_state'),to_regclass('public.app_todo_not_mine'),to_regclass('public.app_todo_feedback'),to_regclass('public.app_todo_rules'))
union all select 'policy',c.relname::text||'.'||p.polname::text,p.polcmd::text||':'||p.polpermissive::text||':'||p.polroles::text||':'||coalesce(pg_get_expr(p.polqual,p.polrelid),'')||':'||coalesce(pg_get_expr(p.polwithcheck,p.polrelid),'') from pg_policy p join pg_class c on c.oid=p.polrelid where p.polrelid in(to_regclass('public.app_todo_candidates'),to_regclass('public.app_todo_ask_rooms'),to_regclass('public.app_todo_radar_state'),to_regclass('public.app_todo_not_mine'),to_regclass('public.app_todo_feedback'),to_regclass('public.app_todo_rules'))
union all select 'history',version,name from supabase_migrations.schema_migrations where version in('20261029090000','20261029120000','20261029210000','20261102030000')
order by 1,2;
